function main(){
  // 拖拽：按下 -> 分步移动 -> 抬起
  auto.touchDown(100, 500);
  auto.touchMove(150, 400, 0);
  auto.touchMove(200, 300, 0);
  auto.touchUp(0);
  // 双指：分别按下两根手指后一起抬起
  auto.touchDown(100, 300, 0);
  auto.touchDown(300, 300, 1);
  auto.touchMove(100, 100, 0);
  auto.touchMove(300, 100, 1);
  auto.touchUp(); // 同时抬起全部
  logd("完成");
}
main();

