  if (h == null) { logd("连接失败"); return; }
  for (let i = 0; i < 50; i++) {
    const ev = ws.poll(h);
    if (ev && ev.type === "message") {
      logd("收到: " + ev.text);
      ws.send(h, "ack:" + ev.text);
